// Links da navbar baseados no role do usuário
export type Role = "guest" | "creator" | "host";

interface Feather {
  src: string;
  width: number;
  height: number;
}

interface NavLink {
  label: string;
  href: string;
  feather: Feather;
  isExternal?: boolean;
  target?: string;
  rel?: string;
  children?: { label: string; href: string }[];
}

export function getNavbarLinks(role: Role): NavLink[] {
  const homeFeather = {
    src: "data:image/svg+xml;base64,",
    width: 64,
    height: 7
  };

  const servicesFeather = {
    src: "data:image/svg+xml;base64,",
    width: 64,
    height: 7
  };

  if (role === "host") {
    return [
      {
        label: "Campaigns",
        href: "/host/campaign",
        feather: homeFeather,
        children: [
          { label: "Campaigns", href: "/host/campaign" },
          { label: "Manage Campaigns", href: "/host/campaign/manage" },
        ],
      },
      {
        label: "Communities",
        href: "/host/communities",
        feather: servicesFeather
      },
      {
        label: "Plans",
        href: "/host/plans",
        feather: servicesFeather
      },
      {
        label: "My Profile",
        href: "/host/profile",
        feather: { ...homeFeather, width: 44, height: 7 }
      },
    ];
  }

  if (role === "creator") {
    return [
      {
        label: "Campaigns",
        href: "/creator",
        feather: homeFeather
      },
      {
        label: "Communities",
        href: "/creator/communities",
        feather: servicesFeather
      },
      {
        label: "My Profile",
        href: "/creator/profile",
        feather: servicesFeather
      },
    ];
  }

  // guest
  return [];
}
